import{_ as e,o as i,c as o,a5 as r}from"./chunks/framework.CXvGqWf0.js";const q=JSON.parse('{"title":"漫画 · 第 67 话 视觉回归测试","description":"","frontmatter":{},"headers":[],"relativePath":"comics/quality/EP.67-visual-regression.md","filePath":"comics/quality/EP.67-visual-regression.md","lastUpdated":1793853676000}'),l={name:"comics/quality/EP.67-visual-regression.md"};function t(s,a,n,d,h,c){return i(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="漫画-·-第-67-话-视觉回归测试" tabindex="-1">漫画 · 第 67 话 视觉回归测试 <a class="header-anchor" href="#漫画-·-第-67-话-视觉回归测试" aria-label="Permalink to &quot;漫画 · 第 67 话 视觉回归测试&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/quality/01-visual-regression">docs/quality/01-visual-regression.md</a> ｜ 原画：<a href="./EP.67-visual-regression.svg">EP.67-visual-regression.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>标签君</strong>：结构师。本话他被「一周红四十次」的快照测试折磨到想关掉流水线。</li><li><strong>码叔</strong>：老工程师。他一句话点破：截图只是证据，判定规则才是测试。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>团队给整页截图做回归，结果时钟、动画和广告位每天都在变。有人把阈值调到 0，连抗锯齿都算失败；有人干脆把这一步设为「允许失败」。码叔带他们改成组件级截图，遮罩动态区域，关闭动画，固定视口与随机数，再设 1% 的差异预算。周失败从 40 次降到 3 次，且 3 次都是真回归。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>整页截图的噪声源太多：实时时钟、轮播、随机头像、字体抗锯齿。判定规则缺失时，测试只能给出「红」或「绿」，团队无法判断该修页面还是修测试，最终选择忽略。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>Playwright 的三个参数对应三类问题：<code>threshold</code> 吸收单像素颜色抖动，<code>maxDiffPixelRatio</code> 控制整体差异比例，<code>animations: &quot;disabled&quot;</code> 消除时间不确定性。动态区域用 <code>mask</code> 遮罩；随机与时间用 <code>addInitScript</code> 冻结。稳定化做在前面，阈值才不用一放再放。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>码叔把用例改成组件级，按 PR 影响面裁剪，基线统一在 CI 容器生成，失败时输出差异图与差异比例。示例里可以切换「1px 位移 / 颜色变化 / 角标丢失 / 抗锯齿噪声」，观察 1% 预算线如何决定通过或失败——颜色变化差异比例可能很小，却仍是重要回归，这提醒团队不能只依赖比例阈值。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>组件级截图比整页稳定，定位回归更直接。</li><li>先稳定化再调阈值：关动画、固定视口、冻结随机与时间。</li><li>动态内容必须遮罩，否则测试永远不稳定。</li><li>基线进版本库、由 CI 生成，更新要经过评审。</li><li>不要追 0 差异，目标是拦住真实回归。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：把 <code>maxDiffPixelRatio</code> 调到 5% 后测试终于稳定了，这样做有什么风险？</p><p><strong>答</strong>：比例阈值过松会漏掉「面积小但重要」的回归，例如图标丢失、状态色变化、按钮文字换行。正确顺序是先做稳定化与遮罩，把噪声压到很低，再用 1% 左右的预算。阈值是兜底，不是解决噪声的主要手段。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>切换改动类型与噪声强度，观察差异比例与判定：<a href="./../../examples/quality/01-visual-regression">examples/quality/01-visual-regression</a></li><li>把预算调到 5%，再看「角标丢失」是否还能被拦住。</li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 68 话《可访问性审计》——92 分不等于任务可用，键盘走查才是真相。</p>',22)])])}const p=e(l,[["render",t]]);export{q as __pageData,p as default};
